```sql
alter table public.teams enable row level security;
alter table public.team_members enable row level security;
alter table public.documents enable row level security;

create or replace function public.is_team_member(p_team_id bigint, p_role text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.team_members tm
    where tm.team_id = p_team_id
      and tm.user_id = auth.uid()
      and tm.role = p_role
  );
$$;

create or replace function public.is_team_member_any(p_team_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.team_members tm
    where tm.team_id = p_team_id
      and tm.user_id = auth.uid()
  );
$$;

create or replace function public.can_edit_document(p_document_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.documents d
    join public.team_members tm on tm.team_id = d.team_id
    where d.id = p_document_id
      and tm.user_id = auth.uid()
      and tm.role = 'editor'
      and d.deleted_at is null
  );
$$;

create or replace function public.enforce_document_update()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.team_id is distinct from old.team_id
     or new.created_by is distinct from old.created_by then
    raise exception 'Document id, team, and creator cannot be changed';
  end if;

  if new.deleted_at is not null and old.deleted_at is null then
    raise exception 'Cannot delete a document via update';
  end if;

  if new.deleted_at is null and old.deleted_at is not null then
    if new.created_by is distinct from auth.uid() then
      raise exception 'Only the creator can undelete a document';
    end if;
  end if;

  if public.is_team_member_any(new.team_id) and public.is_team_member(new.team_id, 'editor') then
    return new;
  end if;

  raise exception 'Cannot edit this document';
end;
$$;

create trigger enforce_document_update
before update on public.documents
for each row
execute function public.enforce_document_update();

create policy teams_select_member
on public.teams
for select
to authenticated
using (public.is_team_member(id, any(null)));

create policy team_members_select_own
on public.team_members
for select
to authenticated
using (user_id = auth.uid());

create policy documents_select_member
on public.documents
for select
to authenticated
using (public.is_team_member_any(team_id) and deleted_at is null);

create policy documents_insert_editor
on public.documents
for insert
to authenticated
with check (
  created_by = auth.uid()
  and public.is_team_member(team_id, 'editor')
  and deleted_at is null
);

create policy documents_update_editor
on public.documents
for update
to authenticated
using (public.is_team_member_any(team_id) and public.is_team_member(team_id, 'editor') and deleted_at is null)
with check (public.is_team_member_any(team_id) and public.is_team_member(team_id, 'editor'));

create policy documents_delete_creator
on public.documents
for delete
to authenticated
using (created_by = auth.uid() and deleted_at is null);

revoke all on public.teams from anon, authenticated;
revoke all on public.team_members from anon, authenticated;
