-- Helper function: check if current user is a member of a team with a specific role
create or replace function public.is_team_member(p_team_id bigint, p_role text)
returns boolean
language sql
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.team_members
    where team_id = p_team_id
      and user_id = auth.uid()
      and role = p_role
  );
$$;

-- Helper function: check if current user is a member of a team (any role)
create or replace function public.is_team_member(p_team_id bigint)
returns boolean
language sql
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.team_members
    where team_id = p_team_id
      and user_id = auth.uid()
  );
$$;

-- Teams policies
create policy "teams_select_members"
  on public.teams
  for select
  to authenticated
  using (public.is_team_member(id));

-- Team members policies
create policy "team_members_select_self"
  on public.team_members
  for select
  to authenticated
  using (user_id = auth.uid());

-- Documents policies
create policy "documents_select_team_members"
  on public.documents
  for select
  to authenticated
  using (
    public.is_team_member(team_id)
    and (deleted_at is null)
  );

create policy "documents_insert_editor"
  on public.documents
  for insert
  to authenticated
  with check (
    user_id = auth.uid()
    and public.is_team_member(team_id, 'editor')
    and deleted_at is null
  );

create policy "documents_update_editor"
  on public.documents
  for update
  to authenticated
  using (
    public.is_team_member(team_id, 'editor')
    and (deleted_at is null)
  )
  with check (
    public.is_team_member(team_id, 'editor')
  );

create policy "documents_delete_creator"
  on public.documents
  for delete
  to authenticated
  using (
    created_by = auth.uid()
    and (deleted_at is null)
  );

-- Prevent anon access (explicit deny via no policies for anon)
-- Prevent service_role bypass issues (service_role bypasses RLS by default)

-- Revoke direct access from anon
revoke all on public.teams from anon;
revoke all on public.team_members from anon;
revoke all on public.documents from anon;

-- Grant authenticated users appropriate access
grant select on public.teams to authenticated;
grant select on public.team_members to authenticated;
grant select, insert, update, delete on public.documents to authenticated;

-- Grant usage on helper functions
grant execute on function public.is_team_member(bigint) to authenticated;
grant execute on function public.is_team_member(bigint, text) to authenticated;

-- Ensure service_role has full access (bypasses RLS, but explicit grants for clarity)
grant all on public.teams to service_role;
grant all on public.team_members to service_role;
grant all on public.documents to service_role;
grant execute on function public.is_team_member(bigint) to service_role;
grant execute on function public.is_team_member(bigint, text) to service_role;
