```sql
alter table public.accounts enable row level security;
alter table public.files enable row level security;
alter table public.file_shares enable row level security;

create or replace function public.is_suspended(p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce((select suspended from public.accounts where user_id = p_user_id), false);
$$;

create or replace function public.can_access_file(p_file_id bigint, p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.files f
    join public.file_shares fs on f.id = fs.file_id
    where f.id = p_file_id
      and f.owner_id = p_user_id
      and (fs.shared_with is null or fs.shared_with = p_user_id)
      and (fs.expires_at is null or fs.expires_at > now())
  );
$$;

create or replace function public.can_edit_file(p_file_id bigint, p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.files f
    join public.file_shares fs on f.id = fs.file_id
    where f.id = p_file_id
      and f.owner_id = p_user_id
      and (fs.shared_with is null or fs.shared_with = p_user_id)
      and fs.can_edit
      and (fs.expires_at is null or fs.expires_at > now())
  );
$$;

create or replace function public.is_file_owner(p_file_id bigint, p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.files f
    where f.id = p_file_id
      and f.owner_id = p_user_id
  );
$$;

create or replace function public.can_see_file_share(p_file_id bigint, p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.file_shares fs
    where fs.file_id = p_file_id
      and (fs.shared_with is null or fs.shared_with = p_user_id)
  );
$$;

create or replace function public.prevent_file_owner_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.owner_id is distinct from old.owner_id then
    raise exception 'file owner cannot be changed';
  end if;

  return new;
end;
$$;

create trigger prevent_file_owner_change_trigger
before update on public.files
for each row
execute function public.prevent_file_owner_change();

create policy "files_select"
on public.files
for select
to authenticated
using (
