  for insert to authenticated
  with check (created_by = auth.uid() and status = 'draft' and private.invoice_status_ok(status));

create policy invoices_update on public.invoices
  for update to authenticated
  using (
    created_by = auth.uid() and status = 'draft'
    or private.is_finance_staff() and status = 'sent'
  )
  with check (
    created_by = auth.uid()
    and private.invoice_status_ok(status)
    and (
      (created_by = auth.uid() and private.invoice_status_transition_ok(status, new.status))
      or (private.is_finance_staff() and status = 'sent' and new.status in ('paid', 'void'))
    )
  );

