```sql
-- Enable RLS on tables
alter table public.finance_staff enable row level security;
alter table public.invoices enable row level security;

-- Helper function to check if user is finance staff
create or replace function public.is_finance_staff(check_user_id uuid)
returns boolean as $$
begin
  return exists (
    select 1 from public.finance_staff where user_id = check_user_id
  );
end;
$$ language plpgsql security definer;

-- Helper function to check if user can read invoice
create or replace function public.can_read_invoice(check_invoice_id bigint)
returns boolean as $$
declare
  target_user uuid := auth.uid();
  invoice_created_by uuid;
begin
  -- Service role bypasses all checks
  if auth.role() = 'service_role' then
    return true;
  end if;

  -- Check if user is anonymous
  if target_user is null then
    return false;
  end if;

  -- Get invoice created_by
  select created_by into invoice_created_by
  from public.invoices
  where id = check_invoice_id;

  -- Finance staff can read all invoices
  if public.is_finance_staff(target_user) then
    return true;
  end if;

  -- Anyone can read their own created invoices
  return invoice_created_by = target_user;
end;
$$ language plpgsql security definer;

-- Helper function to validate invoice update
create or replace function public.validate_invoice_update(
  p_id bigint,
  p_customer text,
  p_amount numeric,
  p_status text
)
returns boolean as $$
declare
  target_user uuid := auth.uid();
  old_invoice_record public.invoices%rowtype;
  old_status text;
  old_created_by uuid;
  is_service_role boolean;
begin
  -- Service role bypasses all checks
  if auth.role() = 'service_role' then
    return true;
  end if;

  -- Check if user is anonymous
  if target_user is null then
    return false;
  end if;

  -- Fetch current invoice
  select * into old_invoice_record
  from public.invoices
  where id = p_id;

  if not found then
    return false;
  end if;

  old_status := old_invoice_record.status;
  old_created_by := old_invoice_record.created_by;

  -- Cannot change creator
  if p_id::text != old_created_by::text then
    return false;
  end if;

  -- Status transition rules
  if old_status = 'draft' then
    -- Creator can change customer and amount, and draft -> sent
    if p_customer is not distinct from old_invoice_record.customer
       and p_amount is not distinct from old_invoice_record.amount
       and (p_status is null or p_status in ('sent', 'draft', 'paid', 'void')) then
      return true;
    end if;
  elsif old_status = 'sent' then
    -- Finance staff can change sent -> paid or void
    if p_status in ('paid', 'void') and public.is_finance_staff(target_user) then
      return true;
    end if;
    return false;
  elsif old_status = 'paid' or old_status = 'void' then
    return false;
  end if;

  return false;
end;
$$ language plpgsql security definer;

-- Helper function to get allowed status transitions
create or replace function public.get_allowed_status(old_status text, old_created_by uuid, is_staff boolean)
returns table (
  allowed_status text[]
) as $$
begin
  if old_status = 'draft' then
    return query
    select array['draft', 'sent'] as allowed_status;
  elsif old_status = 'sent' then
    return query
    select array['paid', 'void'] as allowed_status;
  else
    return query
    select array[]::text[] as allowed_status;
  end if;
end;
$$ language plpgsql stable;

-- INSERT policies
create policy "invoices_insert"
  on public.invoices
  for insert
  to authenticated
  with check (
    created_by = auth.uid() and status = 'draft'
  );

-- UPDATE policies
create policy "invoices_update"
  on public.invoices
  for update
  to authenticated
  using (
    public.validate_invoice_update(id, customer, amount, status)
  )
  with check (
    public.validate_invoice_update(id, customer, amount, status)
  );

-- DELETE policies
create policy "invoices_delete"
  on public.invoices
  for delete
  to authenticated
  using (
    created_by = auth.uid() and status = 'draft'
  );

-- SELECT policies
create policy "invoices_select"
  on public.invoices
  for select
  to authenticated
  using (
    public.can_read_invoice(id)
  );

-- finance_staff policies
create policy "finance_staff_select"
  on public.finance_staff
  for select
