create or replace function public.invoice_before_update()
returns trigger as $$
declare
  target_user uuid := auth.uid();
  old_status text := OLD.status;
  new_status text := NEW.status;
  old_created_by uuid := OLD.created_by;
begin
  -- Service role bypasses all checks
  if auth.role() = 'service_role' then
    return NEW;
  end if;

  -- Prevent changing creator
  if NEW.created_by != old_created_by then
    raise exception 'Cannot change invoice creator';
  end if;

  -- Prevent changing status to draft (only draft -> sent or draft -> draft allowed)
  if old_status != 'draft' and new_status = 'draft' then
    raise exception 'Cannot change status to draft';
  end if;

  -- Validate status transitions
  if old_status = 'draft' then
    -- Creator can change customer and amount
    if NEW.customer is null or NEW.amount is null then
      raise exception 'Customer and amount cannot be null for draft invoice';
    end if;

    -- Can only transition to sent or stay draft
    if new_status not in ('draft', 'sent') then
      raise exception 'Draft invoice can only be changed to sent or stay draft';
    end if;
  elsif old_status = 'sent' then
    -- Only finance staff can update sent invoices
    if not public.is_finance_staff(target_user) then
      raise exception 'Only finance staff can update sent invoices';
    end if;

    -- Cannot change customer or amount
    if NEW.customer is not distinct from OLD.customer or 
       NEW.amount is not distinct from OLD.amount then
      raise exception 'Cannot change customer or amount of sent invoice';
    end if;

    -- Can only transition to paid or void
    if new_status not in ('paid', 'void') then
      raise exception 'Sent invoice can only be changed to paid or void';
    end if;
  else
    raise exception 'Cannot update invoice with status %', old_status;
  end if;

  return NEW;
end;
$$ language plpgsql security definer;

