  invoice_id bigint,
  field_name text,
  new_status text
)
returns boolean as $$
declare
  target_user uuid;
  current_created_by uuid;
  current_status text;
  is_finance boolean;
begin
  target_user := auth.uid();

  -- Get current invoice data
  select created_by, status into current_created_by, current_status
  from public.invoices where id = invoice_id;

  -- Must be authenticated
  if target_user is null then
    return false;
  end if;

  -- Finance staff bypass for sent->paid/void
  is_finance := public.is_finance_staff(target_user);

  if field_name = 'status' then
    -- Status changes are more complex
    if current_status = 'draft' then
      -- Creator can change draft to sent
      if current_created_by = target_user and new_status = 'sent' then
        return true;
      end if;
      return false;
    elsif current_status = 'sent' then
      -- Finance staff can change sent to paid or void
      if is_finance and new_status in ('paid', 'void') then
        return true;
      end if;
      return false;
    end if;
  else
    -- Only creator can update customer/amount, only from draft
    if current_created_by = target_user 
       and current_status = 'draft' 
       and field_name in ('customer', 'amount') then
      return true;
    end if;
  end if;

  return false;
end;
