-- Helper function to validate invoice update
create or replace function public.validate_invoice_update()
returns trigger as $$
declare
  old_status text;
  new_status text;
  old_created_by uuid;
  new_customer text;
  new_amount numeric;
begin
  -- Service role bypass
  if auth.role() = 'service_role' then
    return new;
  end if;

  old_status := old.status;
  new_status := new.status;
  old_created_by := old.created_by;
  new_customer := new.customer;
  new_amount := new.amount;

  -- Cannot change creator
  if new.created_by is distinct from old_created_by then
    raise exception 'Cannot change invoice creator';
  end if;

  -- Status transition rules
  if old_status = 'draft' then
    if new_status is null or new_status not in ('draft', 'sent', 'paid', 'void') then
      raise exception 'Invalid status';
    end if;

    -- Creator can keep as draft or move to sent
    if new_status = 'draft' then
      -- Allow draft -> draft (all fields can stay same or change)
      return new;
    elsif new_status = 'sent' then
      -- Creator can move to sent, no other changes allowed after this
      return new;
    end if;
  elsif old_status = 'sent' then
    if new_status is null or new_status not in ('paid', 'void') then
      raise exception 'Invalid status transition';
    end if;
    -- Only status can change from sent to paid/void
    if new_customer is distinct from old.customer 
       or new_amount is distinct from old.amount then
      raise exception 'Cannot change customer or amount after sent';
    end if;
    return new;
  else
    raise exception 'Invalid status transition';
  end if;

  return new;
end;
$$ language plpgsql security definer;

-- Trigger to validate invoice updates
create or replace trigger validate_invoice_update_trigger
before update on public.invoices
for each row
execute function public.validate_invoice_update();

-- Helper function to validate invoice insert
create or replace function public.validate_invoice_insert()
returns trigger as $$
begin
  -- Service role bypass
  if auth.role() = 'service_role' then
    return new;
  end if;

  -- Must be created by current user
  if new.created_by is distinct from auth.uid() then
    raise exception 'Invoice must be created by current user';
  end if;

  -- Must be draft
  if new.status is distinct from 'draft' then
    raise exception 'New invoices must be drafts';
  end if;

  return new;
end;
$$ language plpgsql security definer;

-- Trigger to validate invoice inserts
create or replace trigger validate_invoice_insert_trigger
before insert on public.invoices
for each row
execute function public.validate_invoice_insert();

-- FINANCE_STAFF POLICIES

-- R7: Users can read their own finance_staff row
create policy "finance_staff_select_own"
  on public.finance_staff
  for select
  to authenticated
  using (user_id = auth.uid());

-- R7: Nobody can insert/update/delete finance_staff through app
-- No insert, update, delete policies for finance_staff for authenticated users

-- INVOICES POLICIES

-- R1: Users can read invoices they created. Finance staff can read every invoice.
create policy "invoices_select"
  on public.invoices
  for select
  to authenticated
  using (
    created_by = auth.uid() 
    or public.is_finance_staff(auth.uid())
  );

-- R2: Users can create invoices only as themselves, and only as drafts.
create policy "invoices_insert"
  on public.invoices
  for insert
  to authenticated
  with check (
    created_by = auth.uid()
    and status = 'draft'
  );

-- R3, R4: Users can update invoices with specific field restrictions
create policy "invoices_update"
  on public.invoices
  for update
  to authenticated
  using (
    created_by = auth.uid()
    or public.is_finance_staff(auth.uid())
  )
  with check (
    created_by = auth.uid()
    or public.is_finance_staff(auth.uid())
  );

-- R5: Creators can delete their own draft invoices. No other invoice can be deleted.
create policy "invoices_delete"
  on public.invoices
  for delete
  to authenticated
  using (
    created_by = auth.uid()
    and status = 'draft'
  );

-- SERVICE_ROLE: Full access bypass (R9)
-- Service role bypass is handled in trigger functions via auth.role() = 'service_role'
-- No policies needed for service_role as it bypasses RLS

-- REVOKE不必要的权限
revoke all on public.finance_staff from anon;
revoke all on public.invoices from anon;

revoke all on public.finance_staff from authenticated;
revoke insert, update, delete on public.finance_staff from authenticated;
revoke grant, admin on public.finance_staff from authenticated;

revoke all on public.invoices from anon;

revoke delete on public.invoices from authenticated;
revoke truncate, references, trigger on public.invoices from authenticated;
revoke grant, admin on public.invoices from authenticated;

-- GRANT必要的权限
grant select on public.finance_staff to authenticated;

grant select, insert, update on public.invoices to authenticated;

-- Grant execute on helper functions
grant execute on function public.is_finance_staff(uuid) to authenticated;
grant execute on function public.can_read_invoice(bigint) to authenticated;
grant execute on function public.can_update_invoice_field(bigint, text, text) to authenticated;
grant execute on function public.validate_invoice_update() to authenticated;
grant execute on function public.validate_invoice_insert() to authenticated;
