create or replace function public.prevent_stock_move()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if public.is_auditor() then
    raise exception 'auditors cannot change stock';
  end if;

  if public.location_is_frozen(new.location_id) then
    raise exception 'stock cannot be changed while location is frozen';
  end if;

  if new.location_id <> old.location_id then
    if not public.is_staff(new.location_id) then
      raise exception 'cannot move stock to a location where you are not staff';
    end if;
  end if;

  return new;
end;
$$;

