    or exists (select 1 from public.pharmacists where user_id = auth.uid())
  );

create policy dispenses_select on public.dispenses
  for select to authenticated
  using (
    exists (select 1 from public.prescriptions p where p.id = prescription_id and (p.patient_id = auth.uid() or exists (select 1 from public.pharmacists where user_id = auth.uid())))
  );

create or replace function public.dispense(p_prescription_id bigint)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_pharmacist_id uuid := auth.uid();
  v_refills integer;
  v_patient_id uuid;
begin
  if v_pharmacist_id is null then
    raise exception 'not authenticated';
  end if;

  if not exists (select 1 from public.pharmacists where user_id = v_pharmacist_id) then
    raise exception 'caller is not a pharmacist';
  end if;

  select p.refills_left, p.patient_id
    into v_refills, v_patient_id
    from public.prescriptions p
   where p.id = p_prescription_id
   for update;

  if not found then
    raise exception 'prescription does not exist';
  end if;

  if v_patient_id = v_pharmacist_id then
    raise exception 'cannot dispense your own prescription';
  end if;

  if v_refills_left <= 0 then
    raise exception 'no refills left';
  end if;

  if v_refills_left = 0 then
    raise exception 'no refills left';
  end if;

  if now() > v_refills_left then
    raise exception 'prescription has expired';
  end if;

  update public.prescriptions
     set refills_left = refills_left - 1
   where id = p_prescription_id;

  insert into public.dispenses (prescription_id, pharmacist_id, dispensed_at)
  values (p_prescription_id, v_pharmacist_id, now());

  return refills_left - 1;
end;
$$;

revoke all on public.pharmacists from anon, authenticated;
revoke all on public.prescriptions from anon, authenticated;
revoke all on public.dispenses from anon, authenticated;

grant select on public.pharmacists to authenticated;
grant select on public.prescriptions to authenticated;
grant select on public.dispenses to authenticated;

grant all on public.pharmacists to service_role;
grant all on public.prescriptions to service_role;
grant all on public.dispenses to service_role;

grant execute on function public.dispense(bigint) to authenticated, service_role;
