$$;

create function private.is_reviewer(p_project_id bigint, p_lang text) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.translators t where t.project_id = p_project_id and t.user_id = auth.uid() and t.lang = p_lang and t.role = 'reviewer')
$$;

create function private.enforce_segment_update() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if new.id is distinct from old.id or new.project_id is distinct from old.project_id or new.lang is distinct from old.lang then
    raise exception 'segment id, project_id and lang are immutable';
  end if;
  if new.status = 'draft' and new.translated_by is distinct from auth.uid() then
    raise exception 'translated_by must be the current user when changing to draft';
  end if;
  if new.status = 'reviewed' and new.translated_by is not null and new.translated_by is distinct from auth.uid() then
    raise exception 'translated_by cannot be changed to another user when reviewing';
  end if;
  if old.status = 'reviewed' then
    raise exception 'reviewed segments cannot be modified';
  end if;
  if new.status = 'reviewed' and not exists (select 1 from public.translators t where t.project_id = old.project_id and t.user_id = auth.uid() and t.lang = old.lang and t.role = 'reviewer') then
    raise exception 'only reviewers can mark a segment as reviewed';
  end if;
  if new.status = 'draft' and exists (select 1 from public.translators t where t.project_id = old.project_id and t.user_id = auth.uid() and t.lang = old.lang and t.role = 'reviewer' and not exists (select 1 from public.translators t2 where t2.project_id = old.project_id and t2.user_id = auth.uid() and t2.lang = old.lang and t2.role = 'translator')) then
    raise exception 'only translators or co-assigned reviewers may draft a segment';
  end if;
  return new;
end
$$;

alter table public.projects enable row level security;
alter table public.translators enable row level security;
alter table public.segments enable row level security;

create policy projects_select on public.projects
  for select to authenticated
  using (exists (select 1 from public.translators t where t.project_id = projects.id and t.user_id = auth.uid()));

create policy translators_select on public.translators
  for select to authenticated
  using (user_id = auth.uid());

create policy translators_insert on public.translators
  for insert to authenticated
  with check (user_id = auth.uid());

create policy segments_select on public.segments
  for select to authenticated
  using (private.is_translator(project_id, lang));

create policy segments_update on public.segments
  for update to authenticated
  using (private.is_translator(project_id, lang) or private.is_reviewer(project_id, lang))
  with check (private.enforce_segment_update());
