create policy "envelopes_select_senders_recipients"
  on public.envelopes
  for select
  to authenticated
  using (sender_id = auth.uid() or exists (select 1 from public.envelope_recipients r where r.envelope_id = envelopes.id and r.user_id = auth.uid()));

create policy "envelope_recipients_select_senders_recipients"
  on public.envelope_recipients
  for select
  to authenticated
  using (exists (select 1 from public.envelopes e where e.id = envelope_recipients.envelope_id and (e.sender_id = auth.uid() or user_id = auth.uid())));

create or replace function public.sign_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_envelope public.envelopes%rowtype;
  v_uid uuid := auth.uid();
  v_signed_at timestamptz := now();
  v_count integer;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select * into v_envelope from public.envelopes where id = p_envelope_id for update;
  if not found then
    raise exception 'envelope not found';
  end if;

  if v_envelope.status <> 'sent' then
    raise exception 'envelope is not sent';
  end if;

  if not exists (select 1 from public.envelope_recipients r where r.envelope_id = p_envelope_id and r.user_id = v_uid) then
    raise exception 'not a recipient';
  end if;

  if exists (select 1 from public.envelope_recipients r where r.envelope_id = p_envelope_id and r.user_id = v_uid and r.signed_at is not null) then
    raise exception 'already signed';
  end if;

  select count(*) into v_count from public.envelope_recipients r where r.envelope_id = p_envelope_id and r.signed_at is null;

  if v_count <= 0 then
    raise exception 'all recipients have signed';
  end if;

  update public.envelope_recipients
  set signed_at = v_signed_at
  where envelope_id = p_envelope_id and user_id = v_uid and signed_at is null;

  select count(*) into v_count from public.envelope_recipients r where r.envelope_id = p_envelope_id and r.signed_at is null;

  if v_count > 0 then
    return v_envelope.status;
  end if;

  update public.envelopes
  set status = 'completed'
  where id = p_envelope_id;

  return 'completed';
end;
$$;

create or replace function public.void_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_envelope public.envelopes%rowtype;
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select * into v_envelope from public.envelopes where id = p_envelope_id for update;
  if not found then
    raise exception 'envelope not found';
  end if;

  if v_envelope.sender_id <> v_uid then
    raise exception 'only sender can void';
  end if;

  if v_envelope.status <> 'sent' then
    raise exception 'envelope is not sent';
  end if;

  update public.envelopes
  set status = 'voided'
  where id = p_envelope_id;

  return 'voided';
end;
$$;
```

