create schema private;

grant usage on schema private to authenticated;

create function private.is_org_admin(p_org_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.org_admins a where a.org_id = p_org_id and a.user_id = auth.uid())
$$;

create function private.can_issue(p_device_id bigint, p_command text) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.devices d
    where d.id = p_device_id
      and (
        (auth.role() = 'service_role')
        or (
          private.is_org_admin(d.org_id)
          and (p_command = 'locate' or p_command = 'lock')
        )
        or (
          d.assigned_to = auth.uid()
          and (p_command = 'locate' or p_command = 'lock')
        )
      )
  )
$$;

alter table public.org_admins enable row level security;
alter table public.devices enable row level security;
alter table public.device_commands enable row level security;

create policy org_admins_select on public.org_admins
  for select to authenticated
  using (private.is_org_admin(org_id));

create policy devices_select on public.devices
  for select to authenticated
  using (assigned_to = auth.uid() or private.is_org_admin(org_id));

create policy device_commands_select on public.device_commands
  for select to authenticated
  using (private.is_org_admin(device_id) or assigned_to = auth.uid());

create policy device_commands_insert on public.device_commands
  for insert to authenticated
  with check (issued_by = auth.uid() and private.can_issue(device_id, command));
