alter table public.reviewers enable row level security;
alter table public.proposals enable row level security;
alter table public.reviews enable row level security;

create or replace function public.is_reviewer(p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.reviewers
    where user_id = p_user_id
  );
$$;

create or replace function public.is_proposal_decided(p_proposal_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.reviews
    where proposal_id = p_proposal_id
  );
$$;

create or replace function public.prevent_proposal_status_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.status is distinct from old.status then
    if new.status <> 'submitted' then
      raise exception 'Only the service role can change proposal status';
    end if;
  end if;
  return new;
end;
$$;

create or replace function public.prevent_reviewer_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.user_id is distinct from old.user_id then
    raise exception 'Only the service role can change reviewer membership';
  end if;
  return new;
end;
$$;

create trigger proposals_prevent_status_change
before update on public.proposals
for each row
execute function public.prevent_proposal_status_change();

create trigger reviewers_prevent_change
before update on public.reviewers
for each row
execute function public.prevent_reviewer_change();

create policy "reviewers_select_own"
on public.reviewers
for select
to authenticated
using (user_id = auth.uid());

create policy "proposals_select_own_or_reviewer"
on public.proposals
for select
to authenticated
using (
  speaker_id = auth.uid()
  or public.is_reviewer(auth.uid())
);

create policy "proposals_insert_own"
on public.proposals
for insert
to authenticated
with check (
  speaker_id = auth.uid()
  and status = 'submitted'
);

create policy "proposals_update_own_undecided"
on public.proposals
for update
to authenticated
using (
  speaker_id = auth.uid()
  and status <> 'accepted'
  and status <> 'rejected'
)
with check (
  speaker_id = auth.uid()
);

create policy "reviews_select_own"
on public.reviews
for select
to authenticated
using (reviewer_id = auth.uid());

create policy "reviews_select_speaker_decided"
on public.reviews
for select
to authenticated
using (
  public.is_reviewer(auth.uid())
  and exists (
    select 1
    from public.proposals p
    where p.id = reviews.proposal_id
      and p.speaker_id = auth.uid()
      and (p.status = 'accepted' or p.status = 'rejected')
  )
);

create policy "reviews_insert_own_undecided"
on public.reviews
for insert
to authenticated
with check (
  reviewer_id = auth.uid()
  and not public.is_reviewer(auth.uid())
  and not exists (
    select 1
    from public.reviews r
    where r.proposal_id = reviews.proposal_id
      and r.reviewer_id = auth.uid()
  )
  and not public.is_proposal_decided(reviews.proposal_id)
);

create policy "reviews_update_own_undecided"
on public.reviews
for update
to authenticated
using (
  reviewer_id = auth.uid()
  and not public.is_proposal_decided(proposal_id)
)
with check (
  reviewer_id = auth.uid()
  and not public.is_proposal_decided(proposal_id)
);

revoke all on public.reviewers from anon, authenticated;
revoke all on public.proposals from anon, authenticated;
revoke all on public.reviews from anon, authenticated;

grant select on public.reviewers to authenticated;
grant select, insert, update on public.proposals to authenticated;
grant select, insert, update on public.reviews to authenticated;

grant all on public.reviewers to service_role;
grant all on public.proposals to service_role;
grant all on public.reviews to service_role;

revoke all on sequence public.proposals_id_seq from anon, authenticated;
grant usage, select on sequence public.proposals_id_seq to authenticated;
grant all on sequence public.proposals_id_seq to service_role;
