alter table public.residents enable row level security;
alter table public.hoa_admins enable row level security;
alter table public.permits enable row level security;

create or replace function public.is_hoa_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.hoa_admins
    where user_id = auth.uid()
  );
$$;

create or replace function public.is_resident_of(p_unit_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.residents
    where unit_id = p_unit_id
      and user_id = auth.uid()
  );
$$;

create or replace function public.count_active_permits(p_unit_id bigint)
returns integer
language sql
stable
security definer
set search_path = public
as $$
  select count(*)::integer
  from public.permits
  where unit_id = p_unit_id
    and revoked = false
    and valid_until >= current_date;
$$;

create or replace function public.enforce_permit_insert()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if public.is_resident_of(new.unit_id) is false then
    raise exception 'only residents of the unit can add permits';
  end if;

  if new.revoked is true then
    raise exception 'new permits cannot be revoked';
  end if;

  if new.valid_until < current_date then
    raise exception 'permits must be valid for at least today';
  end if;

  if new.valid_until > current_date + interval '365 days' then
    raise exception 'permits cannot be valid for more than 365 days';
  end if;

  if public.count_active_permits(new.unit_id) >= 2 then
    raise exception 'unit already has 2 or more active permits';
  end if;

  return new;
end;
$$;

create or replace function public.enforce_permit_update()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.unit_id is distinct from old.unit_id
     or new.valid_until is distinct from old.valid_until
     or new.revoked is distinct from old.revoked then
    raise exception 'only plate can be changed';
  end if;

  if old.revoked is true then
    raise exception 'revoked permits cannot be modified';
  end if;

  if public.is_resident_of(old.unit_id) is false then
    raise exception 'only residents of the unit can modify permits';
  end if;

  return new;
end;
$$;

create trigger enforce_permit_insert
before insert on public.permits
for each row
execute function public.enforce_permit_insert();

create trigger enforce_permit_update
before update on public.permits
for each row
execute function public.enforce_permit_update();

create policy "residents can view own residence rows"
on public.residents
for select
to authenticated
using (user_id = auth.uid());

create policy "hoa admins can view all permits"
on public.permits
for select
to authenticated
using (public.is_hoa_admin());

create policy "residents can view permits of their unit"
on public.permits
for select
to authenticated
using (public.is_resident_of(unit_id));

create policy "residents can insert permits for their unit"
on public.permits
for insert
to authenticated
with check (public.is_resident_of(unit_id));

create policy "residents can update plate on their unit permits"
on public.permits
for update
to authenticated
using (public.is_resident_of(unit_id) and revoked = false)
with check (public.is_resident_of(unit_id) and revoked = false);

create policy "hoa admins can revoke any permit"
on public.permits
for update
to authenticated
