create policy "permits_insert"
  on public.permits
  for insert
  to authenticated
  with check (
    public.is_hoa_admin(auth.uid()) is false
    and public.validate_new_permit(unit_id, plate, valid_until, auth.uid())
  );

-- R3, R4: Update - Residents can update plate only, HOA admins can revoke
create policy "permits_update"
  on public.permits
  for update
  to authenticated
  using (
    -- Allow HOA admins to revoke any permit
    public.is_hoa_admin(auth.uid())
    -- Allow residents to update their unit's permits
    or exists (
      select 1 from public.residents
      where residents.unit_id = permits.unit_id
        and residents.user_id = auth.uid()
    )
  )
  with check (
    -- If HOA admin, can only set revoked
    (public.is_hoa_admin(auth.uid()) and revoked = true)
    -- If resident, can only update plate, cannot change validity or revoke status
    or (
      public.is_hoa_admin(auth.uid()) is false
      and exists (
        select 1 from public.residents
        where residents.unit_id = permits.unit_id
          and residents.user_id = auth.uid()
      )
      and valid_until = old.valid_until
      and revoked = old.revoked
    )
  );

-- R5: No updates to residents or hoa_admins from app
-- (No update policies defined for these tables for authenticated role)

-- R6: Service role bypasses RLS automatically

-- Prevent anon access entirely (no policies for anon)

-- Revoke all from anon explicitly
revoke all on public.residents from anon;
revoke all on public.hoa_admins from anon;
revoke all on public.permits from anon;

-- Ensure authenticated has appropriate base grants
grant select, insert, update on public.permits to authenticated;
grant select on public.residents to authenticated;
grant select on public.hoa_admins to authenticated;

-- Grant usage on sequences for permits insert
grant usage on all sequences in schema public to authenticated;

-- Ensure service_role has full access (bypasses RLS by default, but explicit grants)
grant all on public.residents to service_role;
grant all on public.hoa_admins to service_role;
grant all on public.permits to service_role;
grant all on all sequences in schema public to service_role;
